INSERT INTO announcement (user_id, title, body, scheduled_start, scheduled_end)
VALUES (149, 'Scheduled maintenance this weekend', 'Talent Scout will be read-only on Saturday from 2-6 AM ET while we upgrade the database. Clips and rosters stay viewable; new posts and edits will be rejected during that window.', '2026-06-15 09:00:00', '2026-06-29 09:00:00'),
       (3, 'New: filter rosters by division', 'Athletes can now narrow roster search by division, gender, and sport at the same time. Find it at the top of the Browse Rosters page.', '2026-03-24 08:00:00', '2026-04-14 08:00:00'),
       (3, 'Recruiting dead period begins Monday', 'Per NCAA rules, coaches may not initiate contact during the dead period. Messages sent through Talent Scout will queue and deliver afterward.', '2025-12-11 06:00:00', '2025-12-18 06:00:00'),
       (7, 'Verify your graduation year', 'Openings match on graduation year. If yours is wrong, recruiters will not see you. Update it on your profile page.', '2025-12-06 06:00:00', '2025-12-13 06:00:00'),
       (147, 'Clip uploads now support larger files', 'The upload limit is now 250 MB per clip. Longer full-game film no longer needs to be trimmed before posting.', '2026-04-15 09:00:00', '2026-05-15 09:00:00'),
       (3, 'Welcome to the fall recruiting season', 'Over 400 new openings were posted this month. Check the roster board regularly -- most fill within three weeks.', '2025-11-02 12:00:00', '2025-11-09 12:00:00'),
       (7, 'Reminder: keep your personal records current', 'Records older than a season are hidden from recruiter search results. Add a new entry after each meet to stay visible.', '2026-05-06 06:00:00', '2026-05-13 06:00:00'),
       (149, 'Analyst reports refreshed', 'The analytics dashboards now include this season''s data. Comparisons by sport, gender, and graduation year have been rebuilt.', '2026-09-30 08:00:00', '2026-10-21 08:00:00'),
       (7, 'Report inappropriate comments', 'Every comment has a report action. Reported comments are reviewed by an administrator within 24 hours.', '2026-08-20 08:00:00', '2026-08-27 08:00:00'),
       (149, 'Profile photos coming next term', 'We are testing profile photos with a small group of athletes. Expect a wider rollout after the winter season.', '2026-02-27 09:00:00', '2026-03-29 09:00:00'),
